use super::*;
use crate::DomainError;
use proptest::prelude::*;

// Real git 2.43.0 output, generated by `testdata/diff.sh` (`sh diff.sh testdata`) in a
// temporary repo with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1` and fixed dates. The command
// is `git -c core.quotePath=false diff` with the arguments of [`DIFF_ARGS`], plus `--cached` or
// nothing (worktree); the exceptions are noted on each constant.

/// Worktree: several hunks with a context header (`code.c`), omitted counts
/// (`@@ -1 +1 @@`), trailing newline added, removed and absent on both sides, CRLF, non-
/// UTF-8 content, lines that look like headers (`--- a/fake`, `diff --git`), empty context line.
const TEXT: &[u8] = include_bytes!("testdata/diff-text.bin");
/// The same changes as [`TEXT`] with a hostile configuration (`diff.noprefix`,
/// `diff.mnemonicPrefix`, `diff.external`, `diff.renames=false`, `diff.relative`,
/// `diff.submodule=log`, `color.ui=always`, `core.quotePath=true` in the configuration file and
/// `diff.suppressBlankEmpty`): it differs only in the empty context line without a space.
const CONFIG: &[u8] = include_bytes!("testdata/diff-config.bin");
/// `--cached`: new, deleted and modified binaries, deleted file, mode-only change, new
/// file, exact rename, rename with changes, rename with a mode change, file turned into a
/// symbolic link (deleted + new), renamed empty file (deleted empty + new empty).
const FILE: &[u8] = include_bytes!("testdata/diff-file.bin");
/// `--cached -C --find-copies-harder`: an exact copy.
const COPIES: &[u8] = include_bytes!("testdata/diff-copies.bin");
/// `--cached`: names with newline, non-UTF-8 bytes (`caf\xff.txt`), tab, quotes, space,
/// backslash, UTF-8 (`naïve.txt`) and a rename from a simple name to a quoted one.
const NAMES: &[u8] = include_bytes!("testdata/diff-names.bin");
/// Like [`NAMES`] but with `git diff` without `-c core.quotePath=false`: non-ASCII bytes in octal.
const NAMES_QUOTEPATH: &[u8] = include_bytes!("testdata/diff-names-quotepath.bin");
/// `--cached`: submodule added (with `.gitmodules`).
const SUBMODULE_NEW: &[u8] = include_bytes!("testdata/diff-submodule-new.bin");
/// Worktree: submodule moved to another commit, with `-c diff.submodule=log` added.
const SUBMODULE: &[u8] = include_bytes!("testdata/diff-submodule.bin");
/// Worktree without changes: zero bytes.
const EMPTY: &[u8] = include_bytes!("testdata/diff-empty.bin");
/// Worktree during a merge with two conflicts (one with a tab in the name) and a modified file.
const CONFLICT: &[u8] = include_bytes!("testdata/diff-conflict.bin");
/// `--cached` during the same merge: only `* Unmerged path` lines.
const CONFLICT_INDEX: &[u8] = include_bytes!("testdata/diff-conflict-index.bin");
/// The script that generates the files: it must use the same arguments as [`DIFF_ARGS`].
const SCRIPT: &str = include_str!("testdata/diff.sh");

const EMPTY_BLOB: &str = "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391";
const ZERO: Oid = Oid::from_bytes([0; Oid::LEN]);

fn parse(input: &[u8]) -> Diff {
    parse_diff(input).expect("valid real output")
}

fn reason(input: &[u8]) -> String {
    match parse_diff(input) {
        Err(DomainError::InvalidGitOutput { command, reason }) => {
            assert_eq!(command, "diff");
            reason
        }
        other => panic!("expected an error, got {other:?}"),
    }
}

fn file<'a>(diff: &'a Diff, path: &[u8]) -> &'a FileDiff {
    let mut found = diff.files.iter().filter(|f| f.new_path.as_bytes() == path);
    let f = found.next().expect("file present");
    assert!(found.next().is_none(), "only one file with this path");
    f
}

/// The lines of a hunk as `(prefix, content, old, new, no newline)`.
type Row<'a> = (char, &'a [u8], Option<u32>, Option<u32>, bool);

fn rows(hunk: &Hunk) -> Vec<Row<'_>> {
    hunk.lines
        .iter()
        .map(|l| {
            (
                char::from(l.kind.prefix()),
                l.content.as_bytes(),
                l.old_line,
                l.new_line,
                l.no_newline,
            )
        })
        .collect()
}

fn ranges(hunk: &Hunk) -> (u32, u32, u32, u32) {
    (
        hunk.old_start,
        hunk.old_count,
        hunk.new_start,
        hunk.new_count,
    )
}

#[test]
fn the_script_uses_the_parser_arguments() {
    let args = DIFF_ARGS.join(" ");
    assert!(SCRIPT.contains(&format!("git -c core.quotePath=false diff {args} \"$@\"")));
    assert!(SCRIPT.contains(&format!("git diff {args} --cached")));
    assert!(SCRIPT.contains(&format!("git -c diff.submodule=log diff {args} >")));
}

#[test]
fn empty_output() {
    assert_eq!(parse(EMPTY), Diff::default());
    assert!(EMPTY.is_empty());
}

#[test]
fn text_hunks_and_line_numbers() {
    let diff = parse(TEXT);
    let paths: Vec<&[u8]> = diff.files.iter().map(|f| f.path().as_bytes()).collect();
    assert_eq!(
        paths,
        [
            &b"adds-newline.txt"[..],
            b"both-without.txt",
            b"code.c",
            b"crlf.txt",
            b"fake-headers.txt",
            b"latin1.txt",
            b"line-empty.txt",
            b"one-line.txt",
            b"removes-newline.txt",
        ]
    );
    for f in &diff.files {
        assert_eq!(f.change, Change::Modified);
        assert_eq!(f.old_path, f.new_path);
        assert_eq!((f.old_mode, f.new_mode), (Some(0o100644), Some(0o100644)));
        assert!(f.old_oid.is_some() && f.new_oid.is_some() && f.old_oid != f.new_oid);
        assert!(!f.binary && !f.is_submodule() && f.similarity.is_none());
    }

    let code = file(&diff, b"code.c");
    assert_eq!(
        code.old_oid,
        Some(Oid::from_hex(b"d36507229d9fbdec053a29a3bc64973ca3addbd5").unwrap())
    );
    let [first_hunk, second_hunk] = &code.hunks[..] else {
        panic!("two hunks expected")
    };
    assert_eq!(ranges(first_hunk), (1, 6, 1, 6));
    assert!(first_hunk.section.is_empty());
    assert_eq!(
        rows(first_hunk)[2],
        ('-', &b"    line(2);"[..], Some(3), None, false)
    );
    assert_eq!(
        rows(first_hunk)[3],
        ('+', &b"    line(2); // changed"[..], None, Some(3), false)
    );
    assert_eq!(ranges(second_hunk), (17, 6, 17, 7));
    assert_eq!(second_hunk.section.as_bytes(), b"int main() {");
    assert_eq!(
        rows(second_hunk)[2..5],
        [
            (' ', &b"    line(18);"[..], Some(19), Some(19), false),
            ('+', b"    new();", None, Some(20), false),
            (' ', b"    line(19);", Some(20), Some(21), false),
        ]
    );
    assert_eq!(code.line_counts(), (2, 1));

    // `@@ -1 +1 @@`: omitted counts, that is 1.
    let single = &file(&diff, b"one-line.txt").hunks[0];
    assert_eq!(ranges(single), (1, 1, 1, 1));
    assert_eq!(
        rows(single),
        [
            ('-', &b"only"[..], Some(1), None, false),
            ('+', b"single", None, Some(1), false),
        ]
    );
}

#[test]
fn text_end_of_file_without_newline() {
    let diff = parse(TEXT);
    let adds = &file(&diff, b"adds-newline.txt").hunks[0];
    assert_eq!(
        rows(adds),
        [
            (' ', &b"stays"[..], Some(1), Some(1), false),
            ('-', b"no newline", Some(2), None, true),
            ('+', b"no newline", None, Some(2), false),
        ]
    );
    let removes = &file(&diff, b"removes-newline.txt").hunks[0];
    assert_eq!(
        rows(removes)[1..],
        [
            ('-', &b"with newline"[..], Some(2), None, false),
            ('+', b"with newline", None, Some(2), true),
        ]
    );
    let both = &file(&diff, b"both-without.txt").hunks[0];
    assert_eq!(
        rows(both),
        [
            ('-', &b"old no newline"[..], Some(1), None, true),
            ('+', b"new no newline", None, Some(1), true),
        ]
    );
}

#[test]
fn text_content_in_bytes() {
    let diff = parse(TEXT);
    let crlf = &file(&diff, b"crlf.txt").hunks[0];
    assert_eq!(rows(crlf)[2].1, b"TWO\r");
    let latin1 = &file(&diff, b"latin1.txt").hunks[0];
    assert_eq!(rows(latin1)[0].1, b"caf\xe9");
    assert_eq!(latin1.lines[0].content.to_str(), None);
    assert_eq!(latin1.lines[0].content.to_string_lossy(), "caf\u{fffd}");

    // Lines that look like headers stay hunk lines: the header counts them.
    let fake = &file(&diff, b"fake-headers.txt").hunks[0];
    assert_eq!(
        rows(fake),
        [
            (' ', &b"head"[..], Some(1), Some(1), false),
            ('-', b"-- dashes", Some(2), None, false),
            ('-', "++ naïve".as_bytes(), Some(3), None, false),
            ('+', b"--- a/fake", None, Some(2), false),
            ('+', b"+++ b/fake", None, Some(3), false),
            ('+', b"diff --git a/x b/x", None, Some(4), false),
            (' ', b"tail", Some(4), Some(5), false),
        ]
    );
    let empty = &file(&diff, b"line-empty.txt").hunks[0];
    assert_eq!(rows(empty)[1], (' ', &b""[..], Some(2), Some(2), false));
}

#[test]
fn hostile_configuration_neutralized() {
    assert_ne!(CONFIG, TEXT);
    assert_eq!(parse(CONFIG), parse(TEXT));
}

#[test]
fn new_deleted_renamed_binary_files() {
    let diff = parse(FILE);
    let summary: Vec<(&[u8], &[u8], Change)> = diff
        .files
        .iter()
        .map(|f| (f.old_path.as_bytes(), f.new_path.as_bytes(), f.change))
        .collect();
    assert_eq!(
        summary,
        [
            (
                &b"binary-deleted.bin"[..],
                &b"binary-deleted.bin"[..],
                Change::Deleted
            ),
            (b"binary-new.bin", b"binary-new.bin", Change::Added),
            (b"deleted.txt", b"deleted.txt", Change::Deleted),
            (b"empty-deleted.txt", b"empty-new.txt", Change::Renamed),
            (b"executable.sh", b"executable.sh", Change::Modified),
            (b"image.gif", b"image.gif", Change::Modified),
            (b"kind.txt", b"kind.txt", Change::Deleted),
            (b"kind.txt", b"kind.txt", Change::Added),
            (b"new.txt", b"new.txt", Change::Added),
            (b"rename-exact.txt", b"renamed-exact.txt", Change::Renamed),
            (b"rename-mode.sh", b"renamed-mode.sh", Change::Renamed),
            (
                b"rename-modified.txt",
                b"renamed-modified.txt",
                Change::Renamed
            ),
        ]
    );
    let f = &diff.files;

    // Binaries: no hunks.
    assert!(f[0].binary && f[0].hunks.is_empty());
    assert_eq!((f[0].old_mode, f[0].new_mode), (Some(0o100644), None));
    assert_eq!(f[0].new_oid, Some(ZERO));
    assert!(f[1].binary && f[1].hunks.is_empty());
    assert_eq!((f[1].old_mode, f[1].new_mode), (None, Some(0o100644)));
    assert_eq!(f[1].old_oid, Some(ZERO));
    assert!(f[5].binary && f[5].hunks.is_empty());
    assert_eq!(
        (f[5].old_mode, f[5].new_mode),
        (Some(0o100644), Some(0o100644))
    );

    // Deleted: a hunk that removes everything.
    assert_eq!(ranges(&f[2].hunks[0]), (1, 2, 0, 0));
    assert_eq!(f[2].line_counts(), (0, 2));

    // Mode-only change: no `index` nor hunks.
    assert_eq!(
        (f[4].old_mode, f[4].new_mode),
        (Some(0o100644), Some(0o100755))
    );
    assert_eq!((f[4].old_oid, f[4].new_oid), (None, None));
    assert!(f[4].hunks.is_empty() && !f[4].binary);

    // New: `@@ -0,0 +1 @@`.
    assert_eq!(ranges(&f[8].hunks[0]), (0, 0, 1, 1));
    assert_eq!(
        rows(&f[8].hunks[0]),
        [('+', &b"new"[..], None, Some(1), false)]
    );

    // Exact rename: no modes nor ids.
    assert_eq!(f[9].similarity, Some(100));
    assert_eq!((f[9].old_mode, f[9].old_oid), (None, None));
    assert!(f[9].hunks.is_empty());

    // Rename with changes: hunk with context.
    assert_eq!(f[11].similarity, Some(87));
    assert_eq!(ranges(&f[11].hunks[0]), (2, 3, 2, 4));
    assert_eq!(
        f[11].hunks[0].section.as_bytes(),
        b"content slightly modified, long enough"
    );

    // Rename with a mode change.
    assert_eq!(
        (f[10].old_mode, f[10].new_mode),
        (Some(0o100644), Some(0o100755))
    );
    assert_eq!(f[10].similarity, Some(100));

    // From file to symbolic link: deleted + new with mode 120000 and destination without a newline.
    assert_eq!(f[7].new_mode, Some(0o120000));
    assert_eq!(
        rows(&f[7].hunks[0]),
        [('+', &b"new.txt"[..], None, Some(1), true)]
    );

    // Renamed empty file: exact rename, no hunks.
    assert_eq!(f[3].similarity, Some(100));
    assert!(f[3].hunks.is_empty());
}

#[test]
fn copies() {
    let diff = parse(COPIES);
    let [copy_file] = &diff.files[..] else {
        panic!("one file expected")
    };
    assert_eq!(copy_file.change, Change::Copied);
    assert_eq!(copy_file.old_path.as_bytes(), b"new.txt");
    assert_eq!(copy_file.new_path.as_bytes(), b"copy.txt");
    assert_eq!(copy_file.similarity, Some(100));
    assert!(copy_file.hunks.is_empty());
}

#[test]
fn names_with_quotes_spaces_and_non_utf8_bytes() {
    let diff = parse(NAMES);
    let paths: Vec<&[u8]> = diff.files.iter().map(|f| f.path().as_bytes()).collect();
    assert_eq!(
        paths,
        [
            &b"a\nbreak.txt"[..],
            b"caf\xff.txt",
            "naïve.txt".as_bytes(),
            b"strange \"name\"\twith space.txt",
            b"with\ttab.txt",
            b"with \"quotes\".txt",
            b"with space.txt",
            b"with\\back.txt",
        ]
    );
    for f in diff.files.iter().filter(|f| f.change != Change::Renamed) {
        assert_eq!(f.change, Change::Modified);
        assert_eq!(f.old_path, f.new_path);
        assert_eq!(f.line_counts(), (1, 0), "{}", f.path());
    }
    let rename = &diff.files[3];
    assert_eq!(rename.change, Change::Renamed);
    assert_eq!(rename.old_path.as_bytes(), b"simple.txt");
}

#[test]
fn names_with_octal_quote_path() {
    // The same names decoded from octal escapes; rewritten with `core.quotePath=false`.
    let diff = parse(NAMES_QUOTEPATH);
    assert_eq!(diff, parse(NAMES));
    assert_eq!(diff.to_patch(), NAMES);
}

#[test]
fn submodules() {
    let added_diff = parse(SUBMODULE_NEW);
    let gitmodules = file(&added_diff, b".gitmodules");
    assert_eq!(gitmodules.change, Change::Added);
    assert!(!gitmodules.is_submodule());
    let sub = file(&added_diff, b"sub");
    assert_eq!(sub.change, Change::Added);
    assert!(sub.is_submodule());
    assert_eq!(
        rows(&sub.hunks[0]),
        [(
            '+',
            &b"Subproject commit d03fa616ea10c588d08ca4bcb7da5deb900ebbc3"[..],
            None,
            Some(1),
            false
        )]
    );

    let updated = parse(SUBMODULE);
    let [sub] = &updated.files[..] else {
        panic!("one file expected")
    };
    assert_eq!(sub.change, Change::Modified);
    assert!(sub.is_submodule());
    assert_eq!(
        (sub.old_mode, sub.new_mode),
        (Some(0o160000), Some(0o160000))
    );
    assert_eq!(
        sub.new_oid,
        Some(Oid::from_hex(b"74819de8fc26db6da29179970cb224414576bc57").unwrap())
    );
    assert_eq!(sub.line_counts(), (1, 1));
}

#[test]
fn conflicts_without_hunks() {
    let diff = parse(CONFLICT);
    let summary: Vec<(&[u8], Change, usize)> = diff
        .files
        .iter()
        .map(|f| (f.path().as_bytes(), f.change, f.hunks.len()))
        .collect();
    assert_eq!(
        summary,
        [
            (&b"conflict\tstrange.txt"[..], Change::Unmerged, 0),
            (b"conflict.txt", Change::Unmerged, 0),
            (b"new.txt", Change::Modified, 1),
        ]
    );
    let conflict = &diff.files[0];
    assert_eq!(conflict.old_path, conflict.new_path);
    assert_eq!((conflict.old_mode, conflict.old_oid), (None, None));

    let index = parse(CONFLICT_INDEX);
    let paths: Vec<(&[u8], Change)> = index
        .files
        .iter()
        .map(|f| (f.path().as_bytes(), f.change))
        .collect();
    assert_eq!(
        paths,
        [
            (&b"conflict\tstrange.txt"[..], Change::Unmerged),
            (b"conflict.txt", Change::Unmerged),
        ]
    );
    assert_eq!(index.to_patch(), CONFLICT_INDEX);
}

#[test]
fn unmerged_with_newline_in_the_name() {
    let diff = parse(b"* Unmerged path a\nb\n* Unmerged path c\n");
    let paths: Vec<&[u8]> = diff.files.iter().map(|f| f.path().as_bytes()).collect();
    assert_eq!(paths, [&b"a\nb"[..], b"c"]);
}

#[test]
fn empty_files() {
    // Empty new file (`git add` of an empty file, without other similar files to rename from):
    // `new file mode` and `index`, no `---`/`+++`.
    let input = format!(
        "diff --git a/empty b/empty\nnew file mode 100644\nindex {}..{EMPTY_BLOB}\n",
        ZERO
    );
    let diff = parse(input.as_bytes());
    let [empty] = &diff.files[..] else {
        panic!("one file expected")
    };
    assert_eq!(empty.change, Change::Added);
    assert_eq!(empty.path().as_bytes(), b"empty");
    assert_eq!(
        empty.new_oid,
        Some(Oid::from_hex(EMPTY_BLOB.as_bytes()).unwrap())
    );
    assert!(empty.hunks.is_empty() && !empty.binary);
    assert_eq!(diff.to_patch(), input.as_bytes());
}

/// For outputs without conflicts or particular configuration, [`Diff::to_patch`] rewrites
/// exactly git's bytes.
#[test]
fn identical_rewrite() {
    for (name, input) in [
        ("text", TEXT),
        ("file", FILE),
        ("copies", COPIES),
        ("names", NAMES),
        ("submodule-new", SUBMODULE_NEW),
        ("submodule", SUBMODULE),
        ("empty", EMPTY),
    ] {
        let out = parse(input).to_patch();
        assert!(
            out == input,
            "{name}: rewritten differs\n{}\n---\n{}",
            String::from_utf8_lossy(&out),
            String::from_utf8_lossy(input)
        );
    }
}

#[test]
fn header_and_patch_of_a_file() {
    let diff = parse(TEXT);
    let f = file(&diff, b"one-line.txt");
    let mut header = Vec::new();
    f.write_header(&mut header);
    assert!(header.starts_with(b"diff --git a/one-line.txt b/one-line.txt\nindex "));
    assert!(header.ends_with(b" 100644\n--- a/one-line.txt\n+++ b/one-line.txt\n"));
    assert_eq!(f.hunks[0].header(), b"@@ -1 +1 @@");
    let mut patch = header.clone();
    f.hunks[0].write_to(&mut patch);
    assert_eq!(patch, f.to_patch());
    assert!(patch.ends_with(b"@@ -1 +1 @@\n-only\n+single\n"));
}

#[test]
fn json_with_non_utf8_bytes() {
    let diff = parse(TEXT);
    let latin1 = file(&diff, b"latin1.txt");
    let json = serde_json::to_value(latin1).unwrap();
    assert_eq!(json["old_path"], "latin1.txt");
    assert_eq!(json["change"], "Modified");
    assert_eq!(json["old_mode"], 0o100644);
    assert_eq!(json["old_oid"], "ccfdffe695f049c9ac21e2054099103c7a2cf9ff");
    assert_eq!(json["binary"], false);
    let hunk = &json["hunks"][0];
    assert_eq!(hunk["old_start"], 1);
    assert_eq!(hunk["section"], "");
    assert_eq!(
        hunk["lines"][0],
        serde_json::json!({
            "kind": "Context",
            "old_line": 1,
            "new_line": 1,
            "content": [99, 97, 102, 0xe9],
            "no_newline": false,
        })
    );
    assert_eq!(hunk["lines"][1]["content"], "second");
    assert_eq!(hunk["lines"][1]["new_line"], serde_json::Value::Null);

    for input in [TEXT, FILE, NAMES, CONFLICT] {
        let diff = parse(input);
        let back: Diff = serde_json::from_str(&serde_json::to_string(&diff).unwrap()).unwrap();
        assert_eq!(back, diff);
    }
}

#[test]
fn errors_on_malformed_input() {
    let ok = "diff --git a/x b/x\nindex 0123456789012345678901234567890123456789..\
              1123456789012345678901234567890123456789 100644\n--- a/x\n+++ b/x\n";
    let cases: Vec<(String, &str)> = vec![
        ("diff --git a/x b/x".into(), "does not end with a newline"),
        ("ciao\n".into(), "line 1: unexpected `ciao`"),
        (
            format!("{ok}@@ -1,2 +1 @@\n-a\n"),
            "truncated hunk: 1 lines",
        ),
        (
            format!("{ok}@@ -1 +1 @@\n-a\n+b\n+c\n"),
            "line 8: unexpected `+c` after",
        ),
        (
            format!("{ok}@@ -1 +1 @@\n-a\n?b\n"),
            "line 7: `?b` is not a hunk line",
        ),
        (
            format!("{ok}@@ -1 +0,0 @@\n+a\n"),
            "more lines than declared",
        ),
        (format!("{ok}@@ -x +1 @@\n"), "is not a hunk header"),
        (
            format!("{ok}@@ -1 +1 @@x\n-a\n+b\n"),
            "is not a hunk header",
        ),
        (
            format!("{ok}@@ -1 +1 @@\n\\ No newline\n"),
            "without a line before it",
        ),
        (
            format!("{ok}diff --git a/y b/y\n"),
            "line 5: no hunk after the `+++` line",
        ),
        (
            "diff --git a/x b/x\n--- a/x\nciao\n".into(),
            "line 3: missing `+++` line",
        ),
        (
            "diff --git x x\n--- x\n+++ x\n@@ -1 +1 @@\n-a\n+b\n".into(),
            "does not start with `a/`",
        ),
        (
            "diff --git a/x b/x\nindex abc..def 100644\n".into(),
            "`--full-index`",
        ),
        (
            "diff --git a/x b/x\nold mode 10064x\n".into(),
            "is not a valid octal mode",
        ),
        (
            "diff --git a/x b/x\nsimilarity index 101%\n".into(),
            "is not a valid percentage",
        ),
        ("diff --git a/x b/x\nrename from x\n".into(), "without both"),
        (
            "diff --git a/x b/x\nboh\n".into(),
            "line 2: unknown header `boh`",
        ),
        (
            "diff --git a/x b/x\n@@ -1 +1 @@\n".into(),
            "hunk without the `---`",
        ),
        (
            "diff --git a/x b/x\nGIT binary patch\n".into(),
            "binary patch",
        ),
        (
            "diff --git a/x b/x\ndissimilarity index 90%\n".into(),
            "`-B`",
        ),
        ("diff --git \"a/x\\q\" b/x\n".into(), "unknown escape `\\q`"),
        (
            "diff --git \"a/x\\04\" b/x\n".into(),
            "invalid octal escape",
        ),
        ("diff --git \"a/x b/x\n".into(), "unclosed quotes"),
        (
            "diff --git a/x c b/y d b/z\n".into(),
            "cannot get the paths",
        ),
        (
            "diff --git a/x b/x\nnew file mode 100644\ndeleted file mode 100644\n".into(),
            "different change types",
        ),
        (
            "diff --git a/x b/x\n--- /dev/null\n+++ /dev/null\n".into(),
            "both `/dev/null`",
        ),
        ("diff --cc \"x\n".into(), "unclosed quotes"),
    ];
    for (input, expected) in cases {
        let r = reason(input.as_bytes());
        assert!(
            r.contains(expected),
            "{input:?}: `{r}` does not contain `{expected}`"
        );
    }
}

#[test]
fn quotes_decoded() {
    use super::quote::{unquote, write_quoted};
    assert_eq!(
        unquote(br#""a\tb\n\"\\\a\b\v\f\r\001\377""#).unwrap(),
        b"a\tb\n\"\\\x07\x08\x0b\x0c\r\x01\xff"
    );
    assert_eq!(unquote(b"without quotes").unwrap(), b"without quotes");
    assert!(
        unquote(br#""a" b"#)
            .unwrap_err()
            .contains("after the closing quote")
    );
    let mut out = Vec::new();
    write_quoted(&mut out, b"a/", b"x\x01\x7f\t\xff y");
    assert_eq!(
        out,
        br#""a/x\001\177\t"#.iter().copied().chain(*b"\xff y\"").collect::<Vec<u8>>()
    );
}

fn path_strategy() -> impl Strategy<Value = RepoPath> {
    proptest::collection::vec(1u8..=255, 1..12).prop_map(RepoPath::from)
}

fn content_strategy() -> impl Strategy<Value = Vec<u8>> {
    proptest::collection::vec(
        any::<u8>().prop_filter("niente newline", |b| *b != b'\n'),
        0..10,
    )
}

fn hunk_strategy() -> impl Strategy<Value = Hunk> {
    let line = (0u8..3, content_strategy(), any::<bool>());
    (
        0u32..1000,
        0u32..1000,
        content_strategy(),
        proptest::collection::vec(line, 0..8),
    )
        .prop_map(|(old_start, new_start, section, raw)| {
            let (mut old_no, mut new_no) = (old_start, new_start);
            let lines: Vec<Line> = raw
                .into_iter()
                .map(|(k, content, no_newline)| {
                    let kind = [LineKind::Context, LineKind::Added, LineKind::Removed][k as usize];
                    let old_line = (kind != LineKind::Added).then(|| {
                        old_no += 1;
                        old_no - 1
                    });
                    let new_line = (kind != LineKind::Removed).then(|| {
                        new_no += 1;
                        new_no - 1
                    });
                    Line {
                        kind,
                        old_line,
                        new_line,
                        content: ByteText::from(content),
                        no_newline,
                    }
                })
                .collect();
            Hunk {
                old_start,
                old_count: old_no - old_start,
                new_start,
                new_count: new_no - new_start,
                section: ByteText::from(section),
                lines,
            }
        })
}

/// A consistent [`FileDiff`], as git might produce it.
fn file_strategy() -> impl Strategy<Value = FileDiff> {
    let modes = prop_oneof![
        Just(0o100644u32),
        Just(0o100755),
        Just(0o120000),
        Just(0o160000)
    ];
    let oid = proptest::array::uniform20(any::<u8>()).prop_map(Oid::from_bytes);
    (
        0u8..6,
        path_strategy(),
        path_strategy(),
        0u8..=100,
        (modes.clone(), modes, 0u8..3),
        proptest::option::of((oid.clone(), oid)),
        any::<bool>(),
        proptest::collection::vec(hunk_strategy(), 1..3),
    )
        .prop_map(
            |(kind, old, new, score, (m1, m2, mode_kind), oids, binary, hunks)| {
                let change = [
                    Change::Modified,
                    Change::Added,
                    Change::Deleted,
                    Change::Renamed,
                    Change::Copied,
                    Change::Unmerged,
                ][kind as usize];
                let mut f = FileDiff {
                    old_path: old.clone(),
                    new_path: new,
                    change,
                    similarity: None,
                    old_mode: None,
                    new_mode: None,
                    old_oid: oids.map(|o| o.0),
                    new_oid: oids.map(|o| o.1),
                    binary,
                    hunks: if binary { Vec::new() } else { hunks },
                };
                match change {
                    Change::Added => f.new_mode = Some(m1),
                    Change::Deleted => f.old_mode = Some(m1),
                    // Equal modes only if there is the `index` line reporting them.
                    _ => match mode_kind {
                        0 => {}
                        1 if oids.is_some() => (f.old_mode, f.new_mode) = (Some(m1), Some(m1)),
                        _ if m1 != m2 => (f.old_mode, f.new_mode) = (Some(m1), Some(m2)),
                        _ => {}
                    },
                }
                if matches!(change, Change::Renamed | Change::Copied) {
                    f.similarity = (score % 2 == 0).then_some(score);
                } else {
                    f.new_path = old;
                }
                if change == Change::Unmerged {
                    let path: Vec<u8> = f
                        .old_path
                        .as_bytes()
                        .iter()
                        .map(|&b| if b == b'\n' { b'_' } else { b })
                        .collect();
                    f = super::diff::unmerged_file(RepoPath::from(path));
                }
                f
            },
        )
}

proptest! {
    /// No input makes the parser panic.
    #[test]
    fn never_panics(input in proptest::collection::vec(any::<u8>(), 0..300)) {
        let _ = parse_diff(&input);
    }

    /// No panic either on lines that resemble a diff, randomly mixed.
    #[test]
    fn never_panics_on_diff_lines(
        picks in proptest::collection::vec((0usize..16, content_strategy()), 0..30)
    ) {
        const PIECES: [&[u8]; 16] = [
            b"diff --git a/x b/x", b"diff --git \"a/", b"--- a/x", b"+++ b/x", b"--- /dev/null",
            b"@@ -1 +1 @@", b"@@ -0,0 +1,2 @@ f", b"@@ -4294967295,2 +1 @@", b"-", b"+", b" ",
            b"\\ No newline at end of file", b"index ", b"new file mode 100644",
            b"rename from ", b"* Unmerged path ",
        ];
        let mut input = Vec::new();
        for (i, tail) in picks {
            input.extend_from_slice(PIECES[i]);
            input.extend_from_slice(&tail);
            input.push(b'\n');
        }
        let _ = parse_diff(&input);
    }

    /// A consistent diff rewritten with [`Diff::to_patch`] is read back identical, with arbitrary names and
    /// contents (quotes, newlines, non-UTF-8 bytes).
    #[test]
    fn rewrite_and_reread(files in proptest::collection::vec(file_strategy(), 0..4)) {
        let diff = Diff { files };
        let patch = diff.to_patch();
        let back = parse_diff(&patch);
        prop_assert_eq!(back.as_ref(), Ok(&diff), "{}", String::from_utf8_lossy(&patch));
    }
}
